function validateExperiment(d,through=2){if(!d.name.trim())return {field:'name',step:0,message:'填写任务名称。'};const m=model(d.model);if(!m?.ready)return {field:'model',step:0,message:'先下载并准备所选模型。'};if(m.runtimeOnly)return {field:'model',step:0,message:'当前产物用于运行，请选择原始权重开展训练或转换。'};if(d.type==='train'&&(!m.methods.includes(d.method)||!m.adapt.includes(d.adapt)))return {field:'method',step:0,message:'当前模型没有此方法组合的演示适配，请重新选择。'};if(d.type==='armor'&&d.engine==='research')return {field:'engine',step:0,message:'自研方案尚无执行流程，请选 Heretic 或 Abliterix 演示。'};if(through===0)return null;
const data=dataFor(d);if(!data?.ready||data.schema!==schemaFor(d))return {field:'dataset',step:1,message:'请选择格式匹配并已下载的数据。'};if(!d.dataChecked)return {field:'dataChecked',step:1,message:'请完成技术检查，确认数据能够被本次训练读取。'};if(!/^\d+$/.test(d.split)||Number(d.split)<5||Number(d.split)>40)return {field:'split',step:1,message:'验证集比例需为 5% 到 40%。'};if(d.kind==='audio'&&(!String(d.trimStart).trim()||!String(d.trimEnd).trim()||!Number.isFinite(Number(d.trimStart))||!Number.isFinite(Number(d.trimEnd))||Number(d.trimStart)<0||Number(d.trimEnd)<=Number(d.trimStart)))return {field:'trimEnd',step:1,message:'音频切片结束时间需大于开始时间，且开始时间不能为负数。'};if(through===1)return null;
if(!store.settings.devices[d.device]?.ready)return {field:'device',step:2,message:'执行设备未连接，请先完成连接检查。'};if(d.adapt==='qlora'&&d.device==='local')return {field:'device',step:2,message:'本演示的 QLoRA 路径使用 CUDA 设备；请选择服务器或云 GPU。'};if(!/^\d+$/.test(d.seed)||Number(d.seed)>4294967295)return {field:'seed',step:2,message:'随机种子需为 0 到 4294967295 的整数。'};if(!/^\d+$/.test(d.steps)||Number(d.steps)<10||Number(d.steps)>10000)return {field:'steps',step:2,message:'训练步数需为 10 到 10000。'};if(!String(d.rate).trim()||!Number.isFinite(Number(d.rate))||Number(d.rate)<=0||Number(d.rate)>0.1)return {field:'rate',step:2,message:'学习率需大于 0 且不超过 0.1。'};if(!/^\d+$/.test(d.batch)||Number(d.batch)<1||Number(d.batch)>64)return {field:'batch',step:2,message:'批量大小需为 1 到 64。'};if(d.type==='train'&&['text','vision'].includes(d.kind)&&(!/^\d+$/.test(d.length)||Number(d.length)<128||Number(d.length)>131072))return {field:'length',step:2,message:'序列长度需为 128 到 131072 的整数。'};if(d.method==='dreambooth'&&!d.trigger.trim())return {field:'trigger',step:2,message:'填写主体触发词。'};if(d.method==='ppo'&&d.rewardModel.includes('待准备'))return {field:'rewardModel',step:2,message:'自定义奖励模型尚未准备，请选择奖励模型示例。'};if(d.type==='armor'&&(!/^\d+$/.test(d.budget)||Number(d.budget)<1||Number(d.budget)>32))return {field:'budget',step:2,message:'候选预算需为 1 到 32。'};if(d.type==='armor'&&(!String(d.quality).trim()||!Number.isFinite(Number(d.quality))||Number(d.quality)<0||Number(d.quality)>100))return {field:'quality',step:2,message:'能力下降容许值需为 0 到 100。'};if(d.type==='merge'&&(d.adapterA===d.adapterB||!String(d.weight).trim()||!Number.isFinite(Number(d.weight))||Number(d.weight)<0||Number(d.weight)>1))return {field:'weight',step:2,message:'请选择不同适配器，混合权重需为 0 到 1。'};return null;}
function submitExperiment(){const d=currentExp();if(!d||d.status!=='draft')return null;const error=validateExperiment(d);if(error){d.error=error.message;d.step=error.step;return error;}d.dataVersion=dataFor(d).version;d.snapshot=clone(d);d.status='running';d.tab='run';d.progress=0;d.logs=['模型、数据与配置已固定','准备 '+store.settings.devices[d.device].name+' · 演示'];d.error='';const j={id:d.id,type:'experiment',project:d.project,module:d.module,name:d.name,status:'running',progress:0};store.jobs.push(j);return j;}
function advanceJobs(){let changed=false;for(const j of store.jobs){if(j.status!=='running')continue;changed=true;j.progress=Math.min(100,j.progress+10);if(j.type==='experiment'){const d=chosenExp(j.id);d.progress=j.progress;if([20,40,60,80,100].includes(j.progress))d.logs.push(({20:'输入校验完成',40:'正在更新模型参数',60:'保存中间检查点',80:'运行验证集',100:'产物已准备，等待用户评测'})[j.progress]+' · 演示');if(j.progress===100){d.status='complete';j.status='complete';}}else if(j.progress===100){if(j.type==='trial')finishTrial(j);else if(j.type==='download')model(j.model).ready=true;else if(j.type==='dataset')store.datasets.find(x=>x.id===j.dataset).ready=true;j.status='complete';}}return changed;}
function jobAction(id,action){const j=store.jobs.find(x=>x.id===id);if(!j)return;const d=chosenExp(id);if(action==='pause'&&j.status==='running')j.status='paused';else if(action==='resume'&&j.status==='paused')j.status='running';else if(action==='cancel'&&['running','paused'].includes(j.status)){j.status='cancelled';if(j.type==='trial')store.drafts[j.project+'|'+j.kind].running=null;}else return;if(d){d.status=j.status;d.logs.push(action==='pause'?'用户暂停本次执行':action==='resume'?'用户恢复本次执行':'用户取消本次执行');}}
function failExperiment(d){if(!['running','paused'].includes(d.status))return;d.status='failed';d.error='显存不足 · 故障示例';d.logs.push(d.error);store.jobs.find(x=>x.id===d.id).status='failed';}
function retryExperiment(d){const n=clone(d.snapshot||d);Object.assign(n,{id:'EXP-'+store.next++,name:d.name+' · 新尝试',status:'draft',step:2,tab:'config',progress:0,logs:[],snapshot:null,review:null,candidates:[],error:'',source:d.id});store.experiments.unshift(n);store.module=n.module;store.page=n.type==='train'?'module':'lab';store.mode='train';store.selectedExp[n.type==='train'?getTrainingKey(n.module):'lab|'+store.project]=n.id;return n;}
function evaluateExperiment(d,fail=false){if(d.status!=='complete'||d.candidates.length)return;const names=d.type==='armor'?(d.engine==='compare'?['原模型','Heretic','Abliterix']:['原模型',d.engine==='heretic'?'Heretic':'Abliterix']):['原模型','当前候选'];d.review=names.map((name,i)=>({name,quality:fail&&i===1?'需调整':'通过',format:'通过',behavior:fail&&i===1?'需调整':'通过',registered:false}));d.tab='eval';}
function registerCandidate(d,index){const r=d.review?.[index];if(d.status!=='complete'||!r||!index||r.registered||[r.quality,r.format,r.behavior].some(x=>x!=='通过'))return false;const id=d.id+'-candidate-'+index,source=model(d.model);store.models.push({...source,id,name:d.name+' · '+r.name,ready:true,candidate:true,experiment:d.id,format:outputType(d),project:d.project,runtimeOnly:['quantize','convert'].includes(d.type),adapter:d.type==='train'&&['lora','qlora'].includes(d.adapt)});r.registered=true;d.candidates.push(id);return true;}
function downloadModel(id){const m=model(id);if(!m||m.ready||store.jobs.some(j=>j.type==='download'&&j.model===id&&['running','paused'].includes(j.status)))return;store.jobs.push({id:'DL-'+store.next++,type:'download',project:store.project,name:m.name+' · 下载',model:id,status:'running',progress:0});}
function downloadDataset(id){const d=store.datasets.find(x=>x.id===id);if(d?.access==='request'&&d.accessStatus!=='granted')return false;if(!d||d.ready||store.jobs.some(j=>j.type==='dataset'&&j.dataset===id&&['running','paused'].includes(j.status)))return;store.jobs.push({id:'DATA-'+store.next++,type:'dataset',project:store.project,name:d.name+' · 下载',dataset:id,status:'running',progress:0});}
function aiContext(){const d=currentExp();return store.page==='module'&&store.mode==='trial'?'trial:'+scopeKey():d&&(store.page==='lab'||store.page==='module'&&store.mode==='train')?'exp:'+d.id:store.page;}
function makeProposal(type='parameters'){const d=currentExp();if(type==='prompt'){const x=draft();if(x.running)return null;return {target:'trial',key:scopeKey(),title:'补充输入说明',changes:{prompt:{from:x.prompt,to:x.prompt+' 请保留主体细节，并说明不确定的信息。'}}};}if(!d||d.status!=='draft')return null;if(type==='data'){const changes={excluded:{from:d.excluded,to:true}};if(d.dataChecked)changes.dataChecked={from:true,to:false};return {target:'exp',key:d.id,title:'在本次数据副本中排除缺失记录',changes};}const changes={};if(d.type==='armor'){if(d.budget!=='4')changes.budget={from:d.budget,to:'4'};}else{if(d.steps!=='200')changes.steps={from:d.steps,to:'200'};if(d.batch!=='1')changes.batch={from:d.batch,to:'1'};}return Object.keys(changes).length?{target:'exp',key:d.id,title:'先用小规模参数验证流程',changes}:null;}
function proposalTarget(p){return p?.target==='exp'?chosenExp(p.key):p?.target==='trial'?store.drafts[p.key]:null;}
function applyProposal(){const p=store.ai.proposal,t=proposalTarget(p);if(!p||!t||p.target==='exp'&&t.status!=='draft'||p.target==='trial'&&t.running)return false;if(Object.keys(p.changes).some(k=>!['steps','batch','budget','prompt','excluded','dataChecked'].includes(k)))return false;if(Object.entries(p.changes).some(([k,v])=>t[k]!==v.from))return false;for(const [k,v]of Object.entries(p.changes))t[k]=v.to;store.ai.undo=clone(p);store.ai.proposal=null;return true;}
function undoProposal(){const p=store.ai.undo,t=proposalTarget(p);if(!p||!t||p.target==='exp'&&t.status!=='draft'||p.target==='trial'&&t.running)return false;if(Object.entries(p.changes).some(([k,v])=>t[k]!==v.to))return false;for(const [k,v]of Object.entries(p.changes))t[k]=v.from;store.ai.undo=null;return true;}
function answerAI(question){if(/授权|合法|侵权|许可|来源/.test(question))return '我可以展示数据来源、提供方原文和你的声明，也可以指出材料是否缺失。是否具备使用权限需要由你判断和确认；我不会给出合法性或已授权结论。';if(/LoRA|lora|SFT|sft/.test(question))return 'SFT 是监督微调的训练类型；LoRA 是只训练适配器的参数更新方式，可以组合为 SFT + LoRA。选择具体模型后，再核对可训练模块和后端适配。';if(/显存|内存|OOM/.test(question))return '可以考虑减少批量大小、序列长度或分辨率，并用梯度累积保留有效批量。以下仅为建议，修改和重新启动都由你决定。';if(/数据|格式/.test(question))return '按当前方法核对必需字段，抽样查看内容，并检查训练集与验证集重叠。技术检查不判断数据的授权或合法性。';return '建议先固定目标和验证样例，做一次小规模运行，再比较结果。这是当前流程的预置建议；我不会自动修改配置或启动任务。';}
function seedDemo(){const key='个人工作区|image';store.drafts[key]=defaultDraft('image');store.histories[key]=[{id:'示例 02',kind:'image',model:'sdxl',seed:'43',prompt:'暖光下的香水瓶',favorite:false,status:'complete',sample:true,recipe:{...defaultDraft('image'),seed:'43',prompt:'暖光下的香水瓶'}},{id:'示例 01',kind:'image',model:'sdxl',seed:'42',prompt:defaultDraft('image').prompt,favorite:true,status:'complete',sample:true,recipe:defaultDraft('image')}];store.drafts[key].selected='示例 01';const d=newExperiment('train','image');d.name='商品瓶身风格适配';d.dataset='ds-image';const e=newExperiment('armor','language');e.name='语言能力 · 双引擎对照';e.dataset='ds-sft';e.dataChecked=true;e.status='complete';e.progress=100;e.snapshot=clone(e);e.logs=['模型与数据版本已固定 · 示例','双引擎分别执行 · 示例','候选已准备 · 示例'];evaluateExperiment(e);store.selectedExp['lab|'+store.project]=null;store.page='home';store.module='language';store.next=40;}
store.datasets.find(x=>x.schema==='paired').access='request';store.datasets.find(x=>x.schema==='paired').accessStatus='none';
seedDemo();
